52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    /**
62	     * Syntactic email validation: a non-empty local part, a single '@', and a
63	     * domain with at least one dot-separated label ending in a letter-only TLD.
64	     */
65	    private static final Pattern EMAIL_PATTERN =
66	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    /**
87	     * Normalise a raw telephone number to E.164 form.
88	     *
89	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
90	     * code are kept when present; otherwise country code '+61' is assumed and a
91	     * single leading '0' is dropped from the national digits. The result must have
92	     * between 8 and 15 digits after the '+'.
93	     *
94	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
95	     */
96	    static String toE164(String raw) {
97	        if (raw == null) {
98	            return null;
99	        }
100	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
101	        String digits;
102	        if (cleaned.startsWith("+")) {
103	            digits = cleaned.substring(1);
104	        } else {
105	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
106	            digits = "61" + national;
107	        }
108	        if (!digits.matches("[0-9]{8,15}")) {
109	            return null;
110	        }
111	        return "+" + digits;
112	    }
113	
114	    /**
115	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
116	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
117	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
118	     * input normalises to the empty string.
119	     */
120	    private static String normaliseIdentity(String value) {
121	        if (value == null) {
122	            return "";
123	        }
124	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
125	    }
126	
127	    /**
128	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
129	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
130	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
131	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
132	     * that is both stored and used for every address comparison.
133	     */
134	    static String normaliseAddress(String value) {
135	        if (value == null) {
136	            return "";
137	        }
138	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
139	        if (collapsed.isEmpty()) {
140	            return "";
141	        }
142	        String[] tokens = collapsed.split(" ");
143	        StringBuilder result = new StringBuilder();
144	        for (int i = 0; i < tokens.length; i++) {
145	            if (i > 0) {
146	                result.append(' ');
147	            }
148	            result.append(expandAddressAbbreviation(tokens[i]));
149	        }
150	        return result.toString();
151	    }
152	
153	    /**
154	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
155	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
156	     * returned unchanged.
157	     */
158	    private static String expandAddressAbbreviation(String token) {
159	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
160	        return switch (core) {
161	            case "ST" -> "STREET";
162	            case "RD" -> "ROAD";
163	            case "AVE" -> "AVENUE";
164	            default -> token;
165	        };
166	    }
167	
168	    /**
169	     * Derive the stable, shared household identifier for owners sharing a household. It is a
170	     * deterministic UUID over the normalised last-name and address, so every owner in the same
171	     * household resolves to the same value regardless of the order in which they were created.
172	     */
173	    private static String householdId(String lastNameKey, String addressKey) {
174	        String seed = lastNameKey + "�" + addressKey;
175	        return UUID.nameUUIDFromBytes(seed.getBytes(StandardCharsets.UTF_8)).toString();
176	    }
177	
178	    /**
179	     * Build the customer code for a new owner as {@code '<CITY3>-<LAST3>-<NNNN>'}, where CITY3 is the
180	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
181	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
182	     * owners already in that city at the time the owner was created.
183	     */
184	    private String nextCustomerCode(String city, String lastName) {
185	        String city3 = prefix3(city);
186	        String last3 = prefix3(lastName);
187	        String cityKey = normaliseIdentity(city);
188	        int sequence = (int) this.clinicService.findAllOwners().stream()
189	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
190	            .count() + 1;
191	        return String.format("%s-%s-%04d", city3, last3, sequence);
192	    }
193	
194	    /**
195	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
196	     * Sunday it is advanced to the following Monday; weekday dates are returned unchanged.
197	     */
198	    static LocalDate toBusinessDay(LocalDate date) {
199	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
200	            date = date.plusDays(1);
201	        }
202	        return date;
203	    }
204	
205	    /** Upper-cased first three characters of {@code value} (fewer if it is shorter); "" when null. */
206	    private static String prefix3(String value) {
207	        String letters = value == null ? "" : value;
208	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase();
209	    }
