211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Override
213	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
214	        Collection<Owner> owners;
215	        if (lastName != null) {
216	            owners = this.clinicService.findOwnerByLastName(lastName);
217	        } else {
218	            owners = this.clinicService.findAllOwners();
219	        }
220	        if (owners.isEmpty()) {
221	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	        }
223	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
224	    }
