226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
229	        Owner owner = this.clinicService.findOwnerById(ownerId);
230	        if (owner == null) {
231	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
232	        }
233	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
234	    }
