236	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
237	    @Override
238	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
239	        String telephone = toE164(ownerFieldsDto.getTelephone());
240	        if (telephone == null) {
241	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
242	        }
243	        String email = ownerFieldsDto.getEmail();
244	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
245	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
246	        }
247	        String address = normaliseAddress(ownerFieldsDto.getAddress());
248	        if (address.isEmpty()) {
249	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
250	        }
251	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
252	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
253	        LocalDate registrationDate = toBusinessDay(effectiveDate);
254	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
255	            .map(Owner::getRegistrationDate)
256	            .filter(existing -> existing != null)
257	            .map(OwnerRestControllerV1::toBusinessDay)
258	            .filter(registrationDate::equals)
259	            .count();
260	        if (ownersCreatedThatDay >= 100) {
261	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
262	        }
263	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
264	        long ownersInCity = this.clinicService.findAllOwners().stream()
265	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
266	            .count();
267	        if (ownersInCity >= 50) {
268	            return new ResponseEntity<>(HttpStatus.CONFLICT);
269	        }
270	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
271	            .map(Owner::getTelephone)
272	            .map(OwnerRestControllerV1::toE164)
273	            .filter(existing -> existing != null)
274	            .anyMatch(telephone::equals);
275	        if (telephoneInUse) {
276	            return new ResponseEntity<>(HttpStatus.CONFLICT);
277	        }
278	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
279	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
280	        String addressKey = address;
281	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
282	            .filter(existing ->
283	                normaliseIdentity(existing.getLastName()).equals(lastNameKey)
284	                    && normaliseAddress(existing.getAddress()).equals(addressKey))
285	            .toList();
286	        if (!householdMembers.isEmpty() && !sharesHousehold) {
287	            return new ResponseEntity<>(HttpStatus.CONFLICT);
288	        }
289	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
290	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
291	            .filter(existing ->
292	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
293	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
294	            .count();
295	        HttpHeaders headers = new HttpHeaders();
296	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
297	        owner.setNamesakeCount(namesakeCount);
298	        owner.setAddress(address);
299	        owner.setTelephone(telephone);
300	        owner.setEmail(email == null ? null : email.toLowerCase());
301	        owner.setRegistrationDate(registrationDate);
302	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
303	        if (sharesHousehold && !householdMembers.isEmpty()) {
304	            String householdId = householdId(lastNameKey, addressKey);
305	            owner.setHouseholdId(householdId);
306	            for (Owner member : householdMembers) {
307	                if (member.getHouseholdId() == null) {
308	                    member.setHouseholdId(householdId);
309	                    this.clinicService.saveOwner(member);
310	                }
311	            }
312	        }
313	        this.clinicService.saveOwner(owner);
314	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
315	        headers.setLocation(UriComponentsBuilder.newInstance()
316	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
317	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
318	    }
319	
320	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
321	    @Override
322	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
323	        String telephone = toE164(ownerFieldsDto.getTelephone());
324	        if (telephone == null) {
325	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
326	        }
327	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
328	        if (currentOwner == null) {
329	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
330	        }
331	        String email = ownerFieldsDto.getEmail();
332	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
333	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
334	        }
335	        currentOwner.setAddress(ownerFieldsDto.getAddress());
336	        currentOwner.setCity(ownerFieldsDto.getCity());
337	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
338	        currentOwner.setLastName(ownerFieldsDto.getLastName());
339	        currentOwner.setTelephone(telephone);
340	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
341	        this.clinicService.saveOwner(currentOwner);
342	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
343	    }
344	
345	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
346	    @Transactional
347	    @Override
348	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
349	        Owner owner = this.clinicService.findOwnerById(ownerId);
350	        if (owner == null) {
351	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
352	        }
353	        this.clinicService.deleteOwner(owner);
354	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
355	    }
356	
357	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
358	    @Override
359	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
360	        Owner owner = this.clinicService.findOwnerById(ownerId);
361	        if (owner == null) {
362	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
363	        }
364	        HttpHeaders headers = new HttpHeaders();
365	        Pet pet = petMapper.toPet(petFieldsDto);
366	        owner.setId(ownerId);
367	        pet.setOwner(owner);
368	        pet.getType().setName(null);
369	        this.clinicService.savePet(pet);
370	        PetDto petDto = petMapper.toPetDto(pet);
371	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
372	            .buildAndExpand(pet.getId()).toUri());
373	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
374	    }
375	
376	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
377	    @Override
378	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
379	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
380	        if (currentOwner != null) {
381	            Pet currentPet = this.clinicService.findPetById(petId);
382	            if (currentPet != null) {
383	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
384	                currentPet.setName(petFieldsDto.getName());
385	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
386	                this.clinicService.savePet(currentPet);
387	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
388	            }
389	        }
390	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
391	    }
392	
393	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
394	    @Override
395	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
396	        HttpHeaders headers = new HttpHeaders();
397	        Visit visit = visitMapper.toVisit(visitFieldsDto);
398	        Pet pet = new Pet();
399	        pet.setId(petId);
400	        visit.setPet(pet);
401	        this.clinicService.saveVisit(visit);
402	        VisitDto visitDto = visitMapper.toVisitDto(visit);
403	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
404	            .buildAndExpand(visit.getId()).toUri());
405	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
406	    }
407	
408	
409	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
410	    @Override
411	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
412	        Owner owner = this.clinicService.findOwnerById(ownerId);
413	        if (owner != null) {
414	            Pet pet = owner.getPet(petId);
415	            if (pet != null) {
416	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
417	            }
418	        }
419	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
420	    }
421	}
